const AR_REVERSE_MAP = {};
Object.keys(EN_EXACT_MAP).forEach(arKey => {
    AR_REVERSE_MAP[EN_EXACT_MAP[arKey]] = arKey;
});

function trText(val) {
    if (val === null || val === undefined) return '';
    const str = String(val).trim();
    if (!str) return '';
    if (currentLang === 'en') {
        if (EN_EXACT_MAP[str]) return EN_EXACT_MAP[str];
        if (EN_PHRASES[str]) return EN_PHRASES[str];
        // Units only right after a number (e.g. "45 لتر"); before, "مقدم" became "مft" and "التركيب" became "اLكيب"
        const unit = (re, en) => s => s.replace(new RegExp('(\\d)\\s*' + re + '(?![\\u0600-\\u06FF])', 'g'), `$1 ${en}`);
        return [unit('حصان', 'HP'), unit('بوصة', 'inch'), unit('قدم', 'ft'), unit('متر', 'm'), unit('سم', 'cm'), unit('لتر', 'L'),
            unit('كجم', 'kg'), unit('كيلو', 'kg'), unit('فرد', 'place settings'), unit('محيطي', 'surround')]
            .reduce((s, f) => f(s), str).replace(/ج\.م/g, 'EGP');
    }
    return AR_REVERSE_MAP[str] || str;
}

// English for one Arabic text: exact phrase first, then known phrases inside a longer text
// (floor names, currency, common labels). Returns null when nothing changes.
const AR_CHARS = /[؀-ۿ]/;
let __cgPhraseList = null;
function cgPhraseList() {
    if (__cgPhraseList) return __cgPhraseList;
    // curated words/phrases for texts with numbers (e.g. "ناقص 2", "إجمالي الدور السابع") come first, longest first
    const words = typeof EN_WORDS !== 'undefined' ? EN_WORDS : {};
    __cgPhraseList = Object.keys(words).sort((a, b) => b.length - a.length).map(k => [k, words[k]]);
    return __cgPhraseList;
}
const CG_AR_EDGE = '(^|[\\s\\(\\)\\[\\]:،,\\-–/|·•«»"\'.!؟?+0-9])';
function cgTranslateText(str) {
    const trimmed = String(str).trim();
    if (!trimmed || !AR_CHARS.test(trimmed)) return null;
    if (EN_EXACT_MAP[trimmed]) return String(str).replace(trimmed, EN_EXACT_MAP[trimmed]);
    if (typeof EN_PHRASES !== 'undefined' && EN_PHRASES[trimmed]) return String(str).replace(trimmed, EN_PHRASES[trimmed]);
    let out = String(str), changed = false;
    for (const [ar, en] of cgPhraseList()) {
        if (!out.includes(ar)) continue;
        const re = new RegExp(CG_AR_EDGE + ar.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?=$|[\\s\\(\\)\\[\\]:،,\\-–/|·•«»"\'.!؟?+0-9])', 'g');
        const next = out.replace(re, (m, pre) => pre + en);
        if (next !== out) { out = next; changed = true; }
        if (!AR_CHARS.test(out)) break;
    }
    // never show a half-translated mix; typed data (names, descriptions) stays exactly as written
    return changed && !AR_CHARS.test(out) ? out : null;
}
const CG_TR_ATTRS = ['placeholder', 'title', 'aria-label', 'label'];
function cgTranslateNode(root, lang) {
    if (!root) return;
    if (root.nodeType === 3) { cgTranslateTextNode(root, lang); return; }
    if (root.nodeType !== 1) return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(n => cgTranslateTextNode(n, lang));
    const els = [root, ...root.querySelectorAll('[placeholder],[title],[aria-label],optgroup[label],input[type=button],input[type=submit]')];
    els.forEach(el => {
        if (!el.getAttribute) return;
        CG_TR_ATTRS.forEach(a => {
            if (!el.hasAttribute(a)) return;
            const key = 'data-ar-' + a;
            if (lang === 'en') {
                const v = el.getAttribute(a);
                const t = cgTranslateText(v);
                if (t !== null) { el.setAttribute(key, v); el.setAttribute(a, t); }
            } else if (el.hasAttribute(key)) {
                el.setAttribute(a, el.getAttribute(key)); el.removeAttribute(key);
            }
        });
        if (el.tagName === 'INPUT' && (el.type === 'button' || el.type === 'submit')) {
            if (lang === 'en') { const t = cgTranslateText(el.value); if (t !== null) { el.dataset.arValue = el.value; el.value = t; } }
            else if (el.dataset.arValue) { el.value = el.dataset.arValue; delete el.dataset.arValue; }
        }
    });
}
function cgTranslateTextNode(node, lang) {
    const p = node.parentElement;
    if (!p) return;
    const tag = p.tagName;
    if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || p.isContentEditable || p.closest('.no-translate')) return;
    if (lang === 'en') {
        const t = cgTranslateText(node.nodeValue);
        if (t !== null && t !== node.nodeValue) { node.__cgAr = node.nodeValue; node.__cgEn = t; node.nodeValue = t; }
    } else if (node.__cgAr !== undefined) {
        // only restore if the program hasn't rewritten this text since
        if (node.nodeValue === node.__cgEn) node.nodeValue = node.__cgAr;
        delete node.__cgAr; delete node.__cgEn;
    } else {
        const tr = node.nodeValue.trim();
        if (tr && AR_REVERSE_MAP[tr]) node.nodeValue = node.nodeValue.replace(tr, AR_REVERSE_MAP[tr]);
    }
}
function translateDOMNodes(lang) {
    cgTranslateNode(document.body, lang);
    cgEnsureLangObserver();
}
// Everything the program draws after switching to English (tables, windows, the purchase order, PDFs)
// is translated as it appears, so no page is left half Arabic.
let __cgLangObserver = null, __cgLangQueue = new Set(), __cgLangScheduled = false;
function cgEnsureLangObserver() {
    if (__cgLangObserver || typeof MutationObserver === 'undefined') return;
    __cgLangObserver = new MutationObserver(muts => {
        if (currentLang !== 'en') return;
        muts.forEach(m => {
            if (m.type === 'characterData') __cgLangQueue.add(m.target);
            else if (m.type === 'attributes') __cgLangQueue.add(m.target);
            else m.addedNodes.forEach(n => __cgLangQueue.add(n));
        });
        if (__cgLangScheduled) return;
        __cgLangScheduled = true;
        Promise.resolve().then(() => {
            __cgLangScheduled = false;
            const q = [...__cgLangQueue]; __cgLangQueue.clear();
            q.forEach(n => { if (n.isConnected) cgTranslateNode(n, 'en'); });
        });
    });
    __cgLangObserver.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title'] });
}

