function printCustodyReport() {
    const printArea = document.getElementById('official-print-viewport');
    if (!printArea) return;

    const isAr = currentLang === 'ar';
    const calculated = recalculateCustodyBalances();
    const { rows, rawSearch } = getFilteredCustodyRows(calculated);
    const includeInvoices = Boolean(document.getElementById('custody-print-with-invoices')?.checked);

    const firstDate = rows.length > 0 ? rows[0].date : getFormattedTodayDate(isAr);
    const lastDate = rows.length > 0 ? rows[rows.length - 1].date : getFormattedTodayDate(isAr);

    let totalIn = 0;
    let totalOut = 0;
    const rowParts = [];
    let attachedGalleryHtml = '';

    rows.forEach(r => {
        totalIn += r.inflow;
        totalOut += r.outflow;
        const negNote = r.isNegative ? (r.notes ? `${r.notes} (بالسالب - تغطية شخصية مؤقتة)` : 'بالسالب (تغطية شخصية مؤقتة لحين تحويل الشركة)') : (r.notes || '—');
        // Rows whose text wraps take about twice the height on paper
        const longest = Math.max(String(trText(r.desc)).length / 38, String(negNote).length / 42);
        const weight = longest > 2 ? 3 : (longest > 1 ? 2 : 1);
        rowParts.push({ r, weight, html: `
            <tr>
                <td style="width: 34px; text-align: center !important; font-weight: 800;">${r.serialNum}</td>
                <td style="width: 10%; text-align: center !important; font-weight: 700; white-space: nowrap !important;">${r.date}</td>
                <td class="print-item-name" style="width: 24% !important; min-width: 170px !important; max-width: 225px !important; white-space: normal !important; font-weight: 800 !important;"><strong>${trText(r.desc)}</strong></td>
                <td style="width: 11%; text-align: center !important; font-weight: 800; color: #55524b;">${r.inflow > 0 ? r.inflow.toLocaleString('en-US', { maximumFractionDigits: 2 }) : '—'}</td>
                <td style="width: 11%; text-align: center !important; font-weight: 800; color: #b3261e;">${r.outflow > 0 ? r.outflow.toLocaleString('en-US', { maximumFractionDigits: 2 }) : '—'}</td>
                <td style="width: 11%; text-align: center !important; font-weight: 900; font-size: 0.78rem !important; direction: ltr; color: ${r.isNegative ? '#b3261e' : '#1f1d19'};">${r.balance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                <td class="print-notes-col" style="width: 23% !important; min-width: 155px !important; max-width: 215px !important; font-size: 0.76rem !important; line-height: 1.32 !important; white-space: normal !important;">${negNote}</td>
            </tr>
        ` });

        const inv = custodyInvoicesMap[r.id];
        if (includeInvoices && inv && inv.dataUrl && !inv.mimeType.includes('pdf')) {
            attachedGalleryHtml += `
                <div style="border: 1px solid #c9c3b4; border-radius: 6px; padding: 0.5rem; text-align: center; page-break-inside: avoid;">
                    <div style="font-weight: 800; font-size: 0.8rem; margin-bottom: 0.3rem;">#${r.serialNum} — ${inv.name} (${r.date}: ${trText(r.desc)})</div>
                    <img src="${inv.dataUrl}" style="max-width: 100%; max-height: 240px; object-fit: contain;">
                </div>
            `;
        }
    });

    const lastBal = rows.length > 0 ? rows[rows.length - 1].balance : 0;
    const reportSubtitle = isAr
        ? `جرد العهدة من تاريخ ${firstDate} إلى تاريخ ${lastDate}${rawSearch ? ` — (صنف: ${rawSearch})` : ''}`
        : `Custody Statement from ${firstDate} to ${lastDate}`;

    // Split the rows into paper pages ourselves, so each page carries its own totals:
    // "إجمالي الصفحة" and "الإجمالي حتى هذه الصفحة" (running), and the last page ends with the final total.
    const PAGE_CAPACITY = 34; // row units per A4 page under the header (a row wrapping to 2 or 3 lines counts 2 or 3)
    const pages = [];
    let cur = [], used = 0;
    rowParts.forEach(p => {
        if (cur.length && used + p.weight > PAGE_CAPACITY) { pages.push(cur); cur = []; used = 0; }
        cur.push(p); used += p.weight;
    });
    if (cur.length || !pages.length) pages.push(cur);

    const money = n => n.toLocaleString('en-US', { maximumFractionDigits: 2 });
    const money2 = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const headHtml = `
                    <tr>
                        <th colspan="7" style="background:white !important; border:none !important; border-bottom:1.5px solid #2a2722 !important; padding:0 0 0.55rem 0 !important;">
                            ${buildCenteredPrintHeader(
                                isAr ? 'بيان جرد وتسوية عهدة الشركة' : 'Company Custody Audit & Settlement Report',
                                reportSubtitle
                            )}
                        </th>
                    </tr>
                    <tr>
                        <th style="width: 34px; text-align: center !important;">${isAr ? 'م' : '#'}</th>
                        <th style="width: 10%; text-align: center !important;">${isAr ? 'التاريخ' : 'Date'}</th>
                        <th class="print-item-name" style="width: 24% !important; min-width: 170px !important;">${isAr ? 'اسم الصنف / البيان' : 'Item Name'}</th>
                        <th style="width: 11%; text-align: center !important;">${isAr ? 'وارد' : 'Inflow'}</th>
                        <th style="width: 11%; text-align: center !important;">${isAr ? 'منصرف' : 'Outflow'}</th>
                        <th style="width: 11%; text-align: center !important;">${isAr ? 'المتبقي' : 'Balance'}</th>
                        <th class="print-notes-col" style="width: 23% !important; min-width: 155px !important;">${isAr ? 'ملاحظات' : 'Notes'}</th>
                    </tr>`;
    const totalRow = (label, inV, outV, bal, strong) => `
                    <tr class="custody-page-total${strong ? ' is-final' : ''}">
                        <th colspan="3" style="text-align: inherit;">${label}</th>
                        <th style="text-align: center !important;">${money(inV)}</th>
                        <th style="text-align: center !important;">${money(outV)}</th>
                        <th style="text-align: center !important; direction: ltr;">${bal === null ? '' : `${money2(bal)} ${isAr ? 'ج.م' : 'EGP'}`}</th>
                        <th></th>
                    </tr>`;

    let runIn = 0, runOut = 0;
    const pagesHtml = pages.map((pg, i) => {
        const pIn = pg.reduce((s, p) => s + p.r.inflow, 0);
        const pOut = pg.reduce((s, p) => s + p.r.outflow, 0);
        runIn += pIn; runOut += pOut;
        const isLast = i === pages.length - 1;
        const endBal = pg.length ? pg[pg.length - 1].r.balance : lastBal;
        const pageLabel = pages.length > 1 ? ` — ${isAr ? `صفحة ${i + 1} من ${pages.length}` : `page ${i + 1} of ${pages.length}`}` : '';
        let foot = '';
        if (pages.length > 1) foot += totalRow(`${isAr ? 'إجمالي الصفحة' : 'Page total'}${pageLabel}`, pIn, pOut, null, false);
        foot += isLast
            ? totalRow(isAr ? 'الإجمالي النهائي والرصيد المتبقي' : 'Grand total & ending balance', runIn, runOut, endBal, true)
            : totalRow(isAr ? 'الإجمالي حتى هذه الصفحة (والرصيد في آخرها)' : 'Running total to this page', runIn, runOut, endBal, false);
        return `
            <table class="print-table custody-print-page" style="${isLast ? '' : 'page-break-after: always; break-after: page;'}">
                <thead>${headHtml}</thead>
                <tbody>${pg.map(p => p.html).join('')}${foot}</tbody>
            </table>`;
    }).join('');

    printArea.innerHTML = `
        <div class="voucher-print-container" dir="${isAr ? 'rtl' : 'ltr'}">
            ${pagesHtml}
            ${attachedGalleryHtml ? `
                <div style="margin-top: 1rem;">
                    <h4 style="text-align: center; margin-bottom: 0.6rem; font-weight: 900;">مرفقات وصور الفواتير المعتمدة</h4>
                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem;">
                        ${attachedGalleryHtml}
                    </div>
                </div>
            ` : ''}

            <div class="voucher-signatures">
                <div class="sig-line">${isAr ? 'مدير المرافق' : 'Facilities Manager'}</div>
            </div>
        </div>
    `;

    safeWindowPrint();
}

function exportCustodyToCSVLegacy() {
    const calculated = recalculateCustodyBalances();
    const { rows } = getFilteredCustodyRows(calculated);
    let csv = '\uFEFF';
    csv += 'م,التاريخ,اسم الصنف / البيان,وارد,منصرف,المتبقي,ملاحظات,اسم الفاتورة\n';
    rows.forEach(r => {
        const invName = custodyInvoicesMap[r.id] ? custodyInvoicesMap[r.id].name : '';
        csv += `"${r.serialNum}","${r.date}","${r.desc}","${r.inflow}","${r.outflow}","${r.balance}","${r.notes || ''}","${invName}"\n`;
    });
    downloadCSV(csv, `جرد_عهدة_الشركة_${localTodayStr()}.csv`);
    showToast(currentLang === 'ar' ? 'تم تصدير جرد العهدة إلى ملف إكسيل بنجاح!' : 'Custody exported to Excel!', 'success');
}

