// Electricity sheet: change a current balance or the target and every total updates
function exportElecToCSV(only) {
    const d = elecData.draft;
    const c = computeElec(d);
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'شحن الكهرباء',
        title: 'بيان شحن عدادات الكهرباء للأدوار',
        subtitle: `تاريخ الشحن: ${d.date || elecToday()}   |   الشحنة الجاية: ${elecAddDays(d.date || elecToday(), ELEC_EVERY_DAYS)}`,
        columns: [{ h: 'م', w: 6 }, { h: 'الدور', w: 16 }, { h: 'رقم العداد', w: 15 }, { h: 'رصيد الكارت الحالي', w: 18 }, { h: 'الرصيد الجديد (الشحن)', w: 20 }, { h: 'إجمالي الرصيد بالعداد', w: 20 }, { h: 'المديونية', w: 16 }]
    });
    const last = F + c.rows.length - 1;
    const S = last + 2;              // summary block starts after one empty row
    const T = `$E$${S}`;             // target per meter
    c.rows.forEach((r, i) => {
        const row = F + i;
        sh.add([
            { v: i + 1, s: 'center' },
            { v: r.floor, s: 'textBold' },
            { v: String(r.meter), s: 'inputText' },
            { v: r.current, s: 'input' },
            r.manual ? { v: r.newBal, s: 'input' } : { f: `MAX(0,${T}-D${row})`, v: r.newBal, s: 'gold' },
            { f: `D${row}+E${row}`, v: r.total, s: 'money' },
            { v: r.debt, s: 'input' }
        ], 24);
    });
    sh.add([]);
    const lab = (txt, st) => { st = st || 'totLabel'; return [{ v: txt, s: st }, { v: '', s: st }, { v: '', s: st }, { v: '', s: st }]; };
    const rng = col => `${col}${F}:${col}${last}`;
    const block = [
        [...lab('الإجمالي المطلوب لكل عداد'), { v: c.target, s: 'input' }],
        [...lab('إجمالي الشحن'), { f: `SUM(${rng('E')})`, v: c.totalCharge, s: 'totMoney' }],
        [...lab('المديونية'), { f: `SUM(${rng('G')})`, v: c.totalDebt, s: 'totMoney' }],
        [...lab('الإجمالي بعد المديونية'), { f: `E${S + 1}+E${S + 2}`, v: c.afterDebt, s: 'totMoney' }],
        [...lab('نسبة تحصيل للدفع بالفيزا %'), { v: c.feePct, s: 'input' }],
        [...lab(c.feeFixed ? 'رسوم تحصيل الفيزا (المبلغ الفعلي)' : 'رسوم تحصيل الفيزا'), c.feeFixed ? { v: c.fee, s: 'input' } : { f: `ROUND(E${S + 3}*E${S + 4}/100,2)`, v: c.fee, s: 'totMoney' }],
        [...lab('الإجمالي المطلوب', 'finLabel'), { f: `E${S + 3}+E${S + 5}`, v: c.final, s: 'finMoney' }]
    ];
    block.forEach((cells, i) => { const r = sh.add(cells, i === block.length - 1 ? 30 : 24); sh.merge(`A${r}:D${r}`); });
    sh.add([]);
    const nr = sh.add([{ v: 'الخانات بالخلفية الفاتحة بتتكتب بالإيد (الرصيد الحالي، المديونية، الإجمالي المطلوب، النسبة). الرصيد الجديد = الإجمالي المطلوب − الرصيد الحالي، وكل الإجماليات بتتحسب لوحدها.', s: 'note' }], 34);
    sh.merge(`A${nr}:G${nr}`);
    if (only) return sh;
    CGX.download(sh, `شحن_عدادات_الكهرباء_${d.date || elecToday()}`);
}

// Shared helpers for the Excel sheets below
function cgxToday() { return localTodayStr(); }
function cgxTotalRow(sh, labelSpan, cells, final) {
    const st = final ? 'finLabel' : 'totLabel';
    const lab = [{ v: final ? 'الإجمالي النهائي' : 'الإجمالي', s: st }];
    for (let i = 1; i < labelSpan; i++) lab.push({ v: '', s: st });
    const r = sh.add([...lab, ...cells], final ? 30 : 24);
    if (labelSpan > 1) sh.merge(`A${r}:${CGX.colName(labelSpan - 1)}${r}`);
    return r;
}
const CGX_FLOORS = ['الدور الرابع', 'الدور الخامس', 'الدور السادس', 'الدور السابع', 'الدور الثامن', 'الدور التاسع'];

// Main store: balance = total in − issued (formula), low stock flagged by formula too
function exportInventoryToCSV(only) {
    const trans = getCycleTransactions();
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'المخزن الرئيسي', title: 'كشف المخزن الرئيسي والأرصدة',
        subtitle: `الدورة: ${activeCycleKey}   |   تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'م', w: 6 }, { h: 'اسم الصنف', w: 26 }, { h: 'الفئة', w: 18 }, { h: 'الوحدة', w: 10 }, { h: 'إجمالي الوارد', w: 14 }, { h: 'المنصرف خلال الدورة', w: 16 }, { h: 'الرصيد المتبقي', w: 15 }, { h: 'حد الطلب', w: 11 }, { h: 'الحالة', w: 16 }]
    });
    inventory.forEach((item, i) => {
        const r = F + i;
        const issued = trans.filter(t => t.itemId === item.id).reduce((s, t) => s + Number(t.qty), 0);
        const rem = item.total - issued;
        sh.add([
            { v: i + 1, s: 'center' }, { v: trText(item.name), s: 'textBold' }, { v: trText(item.cat), s: 'text' }, { v: trText(item.unit), s: 'center' },
            { v: Number(item.total) || 0, s: 'inputInt' }, only ? { f: `'استهلاك الأدوار'!J${r}`, v: issued, s: 'int' } : { v: issued, s: 'int' },
            { f: `E${r}-F${r}`, v: rem, s: 'totInt' }, { v: Number(item.minLimit) || 0, s: 'inputInt' },
            { f: `IF(G${r}<=0,"نفذ بالكامل",IF(G${r}<=H${r},"قارب على النفاذ","متوفر"))`, v: rem <= 0 ? 'نفذ بالكامل' : (rem <= item.minLimit ? 'قارب على النفاذ' : 'متوفر'), s: 'center' }
        ]);
    });
    const L = F + inventory.length - 1;
    cgxTotalRow(sh, 4, [{ f: `SUM(E${F}:E${L})`, s: 'totInt' }, { f: `SUM(F${F}:F${L})`, s: 'totInt' }, { f: `SUM(G${F}:G${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }, { v: '', s: 'totLabel' }]);
    if (only) return sh;
    CGX.download(sh, `كشف_المخزن_الرئيسي_${cgxToday()}`);
}

// Issue log (filtered like the screen): total quantity by formula
function exportHistoryToCSV(only) {
    // in the full buffet file: the current cycle (month), all floors, oldest first (the screen filters are ignored)
    const logs = only ? [...getCycleTransactions()].sort((a, b) => (a.date || '').localeCompare(b.date || '') || (a.id || 0) - (b.id || 0)) : getHistoryRangeLogs();
    const F = CGX.FIRST;
    const range = only ? `الدورة الحالية: ${activeCycleKey}` : ((historyDateFrom || historyDateTo) ? `من ${historyDateFrom || '...'} إلى ${historyDateTo || '...'}` : `الدورة: ${activeCycleKey}`);
    const sh = CGX.report({
        name: 'سجل الحركات', title: 'سجل حركات الصرف والتدقيق',
        subtitle: `${range}   |   الدور: ${only || activeFloorFilter === 'الكل' ? 'كل الأدوار' : activeFloorFilter}   |   تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'م', w: 6 }, { h: 'التاريخ', w: 13 }, { h: 'الطابق', w: 15 }, { h: 'اسم الصنف', w: 24 }, { h: 'الوحدة', w: 10 }, { h: 'الكمية المنصرفة', w: 15 }, { h: 'اسم المستلم', w: 20 }, { h: 'ملاحظات', w: 24 }]
    });
    logs.forEach((t, i) => {
        const item = inventory.find(x => x.id === t.itemId);
        sh.add([{ v: i + 1, s: 'center' }, { v: t.date || '', s: 'center' }, { v: trText(t.floor), s: 'text' }, { v: item ? trText(item.name) : 'صنف غير معرف', s: 'textBold' }, { v: item ? trText(item.unit) : '', s: 'center' }, { v: Number(t.qty) || 0, s: 'int' }, { v: trText(t.recipient || ''), s: 'text' }, { v: t.notes || '', s: 'text' }]);
    });
    const L = F + Math.max(logs.length, 1) - 1;
    cgxTotalRow(sh, 5, [{ f: `SUM(F${F}:F${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }, { v: '', s: 'totLabel' }]);
    if (only) return sh;
    CGX.download(sh, `سجل_حركات_الصرف_${cgxToday()}`);
}

// Floors consumption: row totals and floor totals are SUM formulas
function exportFloorsMatrixToCSV(only) {
    const trans = getCycleTransactions();
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'استهلاك الأدوار', title: 'تحليل استهلاك الطوابق (4 - 9)',
        subtitle: `الدورة: ${activeCycleKey}   |   تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'م', w: 6 }, { h: 'اسم الصنف', w: 24 }, { h: 'الوحدة', w: 10 }, ...CGX_FLOORS.map(f => ({ h: f, w: 12 })), { h: 'الإجمالي', w: 12 }],
        landscape: true
    });
    inventory.forEach((item, i) => {
        const r = F + i;
        const q = CGX_FLOORS.map(fl => trans.filter(t => t.itemId === item.id && t.floor === fl).reduce((s, t) => s + Number(t.qty), 0));
        sh.add([{ v: i + 1, s: 'center' }, { v: trText(item.name), s: 'textBold' }, { v: trText(item.unit), s: 'center' }, ...q.map((v, k) => only ? { f: `'${CGX_FLOORS[k]}'!D${r}`, v, s: 'int' } : { v, s: 'int' }), { f: `SUM(D${r}:I${r})`, v: q.reduce((a, b) => a + b, 0), s: 'totInt' }]);
    });
    const L = F + inventory.length - 1;
    cgxTotalRow(sh, 3, ['D', 'E', 'F', 'G', 'H', 'I', 'J'].map(c => ({ f: `SUM(${c}${F}:${c}${L})`, s: 'totInt' })));
    if (only) return sh;
    CGX.download(sh, `تحليل_استهلاك_الطوابق_${cgxToday()}`);
}

// Buffet supplier purchase order: line total = qty × price, grand total = SUM
function exportPurchaseOrderToCSV(only) {
    const trans = getCycleTransactions();
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'أمر شراء البوفيه', title: 'أمر شراء للمورد (البوفيه)',
        subtitle: `الدورة: ${activeCycleKey}   |   تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'م', w: 6 }, { h: 'اسم الصنف', w: 24 }, { h: 'الوحدة', w: 10 }, { h: 'الرصيد الحالي', w: 13 }, { h: 'المنصرف', w: 11 }, { h: 'الكمية المطلوبة', w: 15 }, { h: 'سعر الوحدة', w: 13 }, { h: 'الإجمالي', w: 15 }, { h: 'ملاحظات', w: 22 }]
    });
    inventory.forEach((item, i) => {
        const r = F + i;
        const issued = trans.filter(t => t.itemId === item.id).reduce((s, t) => s + Number(t.qty), 0);
        const e = poPricingMap[item.id] || {};
        const qty = e.qty !== undefined ? Number(e.qty) : issued;
        const price = Number(e.unitPrice) || 0;
        sh.add([{ v: i + 1, s: 'center' }, { v: trText(item.name), s: 'textBold' }, { v: trText(item.unit), s: 'center' }, only ? { f: `'المخزن الرئيسي'!G${r}`, v: item.total - issued, s: 'int' } : { v: item.total - issued, s: 'int' }, only ? { f: `'استهلاك الأدوار'!J${r}`, v: issued, s: 'int' } : { v: issued, s: 'int' }, (only && e.qty === undefined) ? { f: `E${r}`, v: qty, s: 'inputInt' } : { v: qty, s: 'inputInt' }, { v: price, s: 'input' }, { f: `F${r}*G${r}`, v: +(qty * price).toFixed(2), s: 'gold' }, { v: e.notes || '', s: 'text' }]);
    });
    const L = F + inventory.length - 1;
    cgxTotalRow(sh, 7, [{ f: `SUM(H${F}:H${L})`, s: 'finMoney' }, { v: '', s: 'finLabel' }], true);
    if (only) return sh;
    CGX.download(sh, `أمر_شراء_المورد_${cgxToday()}`);
}

// One floor's issues for the cycle: the user types what the floor took, and it flows by formula into
// "استهلاك الأدوار" (that floor's column), then "المخزن الرئيسي" (issued, balance) and the supplier order (issued, qty)
