// Custody ledger: running balance = previous balance + in − out (formula on every row)
function exportCustodyToCSV(only) {
    const calculated = recalculateCustodyBalances();
    // in the full custody file: the whole record from the start (screen filters ignored)
    const { rows, rawSearch } = only ? { rows: calculated, rawSearch: '' } : getFilteredCustodyRows(calculated);
    const F = CGX.FIRST;
    const first = rows[0], lastR = rows[rows.length - 1];
    const sh = CGX.report({
        name: 'جرد العهدة', title: 'بيان جرد وتسوية عهدة الشركة',
        subtitle: rows.length ? `من ${first.date} إلى ${lastR.date}${rawSearch ? `   |   صنف: ${rawSearch}` : ''}` : `تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'م', w: 6 }, { h: 'التاريخ', w: 12 }, { h: 'اسم الصنف / البيان', w: 32 }, { h: 'وارد', w: 14 }, { h: 'منصرف', w: 14 }, { h: 'المتبقي', w: 15 }, { h: 'ملاحظات', w: 26 }, { h: 'اسم الفاتورة', w: 18 }]
    });
    rows.forEach((x, i) => {
        const r = F + i;
        const opening = +(x.balance - x.inflow + x.outflow).toFixed(2);
        sh.add([
            { v: x.serialNum, s: 'center' }, { v: x.date, s: 'center' }, { v: trText(x.desc), s: 'textBold' },
            { v: x.inflow || 0, s: 'money' }, { v: x.outflow || 0, s: x.outflow ? 'moneyBad' : 'money' },
            i === 0 ? { f: `${opening}+D${r}-E${r}`, v: x.balance, s: x.balance < 0 ? 'moneyBad' : 'totMoney' } : { f: `F${r - 1}+D${r}-E${r}`, v: x.balance, s: x.balance < 0 ? 'moneyBad' : 'totMoney' },
            { v: x.notes || '', s: 'text' }, { v: custodyInvoicesMap[x.id] ? custodyInvoicesMap[x.id].name : '', s: 'text' }
        ]);
    });
    const L = F + Math.max(rows.length, 1) - 1;
    cgxTotalRow(sh, 3, [{ f: `SUM(D${F}:D${L})`, s: 'finMoney' }, { f: `SUM(E${F}:E${L})`, s: 'finMoney' }, { f: `F${L}`, s: 'finMoney' }, { v: '', s: 'finLabel' }, { v: '', s: 'finLabel' }], true);
    if (only) { sh.dataLast = L; sh.totIn = rows.reduce((s, x) => s + (x.inflow || 0), 0); sh.totOut = rows.reduce((s, x) => s + (x.outflow || 0), 0); return sh; }
    CGX.download(sh, `جرد_عهدة_الشركة_${cgxToday()}`);
}

