// Month comparison: offer total = consumption × price for each month, change columns by formula
function exportFloorsCompareToCSV() {
    const { months, rows } = buildFloorsCompareData();
    if (!months.length) return;
    const F = CGX.FIRST;
    const cols = [{ h: 'م', w: 6 }, { h: 'الصنف', w: 22 }, { h: 'الوحدة', w: 9 }];
    months.forEach(k => { const l = cycleShortLabel(k); cols.push({ h: `استهلاك ${l}`, w: 13 }, { h: `سعر ${l}`, w: 12 }, { h: `إجمالي العرض ${l}`, w: 15 }); });
    const multi = months.length >= 2;
    if (multi) cols.push({ h: 'فرق الاستهلاك', w: 13 }, { h: 'فرق السعر', w: 12 }, { h: 'فرق الإجمالي', w: 14 });
    const sh = CGX.report({ name: 'مقارنة الشهور', title: 'مقارنة الشهور: الاستهلاك وسعر الشراء وإجمالي العرض', subtitle: `الأدوار: ${floorsCompareFloor === 'الكل' ? 'كل الأدوار' : floorsCompareFloor}   |   تاريخ التقرير: ${cgxToday()}`, columns: cols, landscape: true });
    const C = CGX.colName;
    rows.forEach((x, i) => {
        const r = F + i;
        const cells = [{ v: i + 1, s: 'center' }, { v: trText(x.item.name), s: 'textBold' }, { v: trText(x.item.unit), s: 'center' }];
        x.cells.forEach((c, m) => {
            const q = 3 + m * 3;
            cells.push({ v: c.qty, s: 'int' }, { v: c.price, s: 'input' }, { f: `${C(q)}${r}*${C(q + 1)}${r}`, v: c.total, s: 'gold' });
        });
        if (multi) {
            const a = 3, b = 3 + (months.length - 1) * 3;
            cells.push({ f: `${C(b)}${r}-${C(a)}${r}`, s: 'int' }, { f: `${C(b + 1)}${r}-${C(a + 1)}${r}`, s: 'money' }, { f: `${C(b + 2)}${r}-${C(a + 2)}${r}`, s: 'money' });
        }
        sh.add(cells);
    });
    const L = F + Math.max(rows.length, 1) - 1;
    const tot = [];
    months.forEach((k, m) => { const q = 3 + m * 3; tot.push({ f: `SUM(${C(q)}${F}:${C(q)}${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }, { f: `SUM(${C(q + 2)}${F}:${C(q + 2)}${L})`, s: 'totMoney' }); });
    if (multi) { const a = 3, b = 3 + (months.length - 1) * 3; const tr = L + 1; tot.push({ f: `${C(b)}${tr}-${C(a)}${tr}`, s: 'totInt' }, { v: '', s: 'totLabel' }, { f: `${C(b + 2)}${tr}-${C(a + 2)}${tr}`, s: 'totMoney' }); }
    cgxTotalRow(sh, 3, tot);
    CGX.download(sh, `مقارنة_الشهور_${cgxToday()}`);
}

// Floors by department: needed = offices × per office, missing = MAX(0, needed − counted), free offices = offices − staff
function exportDeptsToCSV(only) {
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'الأقسام', title: 'تحليل الطوابق بالأقسام',
        subtitle: `تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'الدور', w: 14 }, { h: 'القسم / المكتب', w: 26 }, { h: 'إجمالي المكاتب (المتفق عليه)', w: 16 }, { h: 'الغرض', w: 22 }, { h: 'العدد المطلوب', w: 13 }, { h: 'الموجود حالياً', w: 13 }, { h: 'محتاج شراء', w: 12 }, { h: 'ملاحظات', w: 24 }],
        landscape: true
    });
    DEPT_FLOORS.forEach(fl => {
        const depts = deptLayout.filter(d => d.floor === fl);
        if (!depts.length) return;
        const gr = sh.add([{ v: fl, s: 'group' }, ...Array(7).fill({ v: '', s: 'group' })]);
        sh.merge(`A${gr}:H${gr}`);
        depts.forEach(d => {
            const items = (d.items || []).filter(it => it.name);
            const rowsOf = items.length ? items : [{ name: '', per: 0, have: null }];
            rowsOf.forEach((it, k) => {
                const r = sh.row();
                const hInfo = it.name ? deptItemHaveInfo(d, it) : null;
                const counted = !!hInfo;
                sh.add([
                    { v: k === 0 ? fl : '', s: 'text' }, { v: k === 0 ? (isBuffetArea(d) ? `${d.name} (بوفيه)` : d.name) : '', s: k === 0 ? 'textBold' : 'text' },
                    k === 0 && !isBuffetArea(d) ? { v: Number(d.offices) || 0, s: 'inputInt' } : { v: '', s: 'text' },
                    { v: it.name || '', s: 'text' },
                    it.name ? { v: deptItemNeed(d, it), s: 'inputInt' } : { v: '', s: 'text' },
                    counted ? { v: hInfo.have, s: 'inputInt' } : { v: '', s: 'inputInt' },
                    { f: `IF(F${r}="","",MAX(0,E${r}-F${r}))`, s: 'totInt' },
                    { v: k === 0 ? (d.notes || '') : '', s: 'text' }
                ]);
            });
        });
    });
    const L = sh.rows.length;
    sh.add([]);
    cgxTotalRow(sh, 2, [{ f: `SUM(C${F}:C${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }, { f: `SUM(E${F}:E${L})`, s: 'totInt' }, { f: `SUM(F${F}:F${L})`, s: 'totInt' }, { f: `SUM(G${F}:G${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }]);
    if (only) return sh;
    CGX.download(sh, `تحليل_الطوابق_بالأقسام_${cgxToday()}`);
}

// Company assets: per-floor counts, company total = SUM, value = total × unit price
function exportFurnitureToCSV(only) {
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'جرد أصول الشركة', title: 'جرد أصول الشركة (الأدوار 4 - 9)',
        subtitle: `تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'الكود', w: 8 }, { h: 'اسم الصنف / البيان', w: 26 }, { h: 'المقاس', w: 12 }, ...CGX_FLOORS.map(f => ({ h: f, w: 9 })), { h: 'الإجمالي', w: 10 }, { h: 'تاريخ الشراء', w: 13 }, { h: 'السعر', w: 11 }, { h: 'القيمة', w: 13 }, { h: 'ملاحظات', w: 24 }],
        landscape: true
    });
    const L = cgxFurnitureRows(sh, 14, (item, i, r) => {
        const q = CGX_FLOORS.map(fl => Number((item.floors || {})[fl]) || 0);
        const sum = q.reduce((a, b) => a + b, 0);
        const fin = getFurnitureItemFinancials(item, sum);
        return [
            { v: item.code || String(i + 1), s: 'center' }, { v: trText(item.name), s: 'textBold' }, { v: trText(item.size) || '—', s: 'center' },
            ...q.map((v, k) => only ? { f: `'${CGX_FLOORS[k]}'!D${r}`, v, s: 'int' } : { v, s: 'inputInt' }),
            { f: `SUM(D${r}:I${r})`, v: sum, s: 'totInt' },
            { v: fin.dateDisplay || '—', s: 'center' },
            fin.hasBatches ? { v: fin.priceDisplay, s: 'center' } : (fin.unitPrice > 0 ? { v: fin.unitPrice, s: 'input' } : { v: '', s: 'input' }),
            fin.hasBatches ? { v: fin.totalCost, s: 'money' } : { f: `IF(L${r}="","",J${r}*L${r})`, v: fin.totalCost || '', s: 'gold' },
            { v: getFurnitureMatrixNoteText(item) || '', s: 'text' }
        ];
    });
    cgxTotalRow(sh, 3, [...['D', 'E', 'F', 'G', 'H', 'I', 'J'].map(c => ({ f: `SUM(${c}${F}:${c}${L})`, s: 'totInt' })), { v: '', s: 'totLabel' }, { v: '', s: 'totLabel' }, { f: `SUM(M${F}:M${L})`, s: 'totMoney' }, { v: '', s: 'totLabel' }]);
    if (only) return sh;
    CGX.download(sh, `جرد_أصول_الشركة_${cgxToday()}`);
}

// Senior management HQ
function exportHqToCSV() {
    const F = CGX.FIRST;
    const sh = CGX.report({
        name: 'مقر الإدارة العليا', title: 'جرد وتجهيزات مقر الإدارة العليا',
        subtitle: `تاريخ التقرير: ${cgxToday()}`,
        columns: [{ h: 'الكود', w: 8 }, { h: 'اسم الصنف / البيان', w: 28 }, { h: 'المقاس', w: 16 }, { h: 'المجموعة', w: 18 }, { h: 'العدد', w: 10 }, { h: 'الحالة', w: 14 }, { h: 'ملاحظات', w: 30 }]
    });
    hqInventory.forEach((item, i) => {
        sh.add([{ v: item.code || String(i + 1), s: 'center' }, { v: trText(item.name), s: 'textBold' }, { v: item.size || '', s: 'center' }, { v: trText(item.cat || ''), s: 'text' }, { v: Number(item.qty) || 0, s: 'inputInt' }, { v: trText(item.status || 'ممتاز'), s: 'center' }, { v: item.notes || '', s: 'text' }]);
    });
    const L = F + hqInventory.length - 1;
    cgxTotalRow(sh, 4, [{ f: `SUM(E${F}:E${L})`, s: 'totInt' }, { v: '', s: 'totLabel' }, { v: '', s: 'totLabel' }]);
    CGX.download(sh, `جرد_مقر_الإدارة_العليا_${cgxToday()}`);
}

// Departments PDF: all floors, one floor ({ floor }) or one department ({ deptId })
// Columns: department · total offices (agreed) · each office item (current, of required, missing) · what to buy
function printDeptsReport(opts) {
    opts = opts || {};
    const isAr = currentLang === 'ar';
    let list = deptLayout;
    let title = 'تحليل الطوابق بالأقسام';
    if (opts.deptId) {
        const d = deptLayout.find(x => x.id === opts.deptId);
        if (!d) return;
        list = [d];
        title = `محتويات ${d.name} — ${d.floor}`;
    } else if (opts.floor) {
        list = deptLayout.filter(x => x.floor === opts.floor);
        title = `تحليل ${opts.floor} بالأقسام`;
    }
    const floors = DEPT_FLOORS.filter(fl => list.some(d => d.floor === fl));

    // One department: a clear item list (item · required · current · to buy)
    if (opts.deptId) {
        const d = list[0];
        const body = (d.items || []).filter(it => it.name).map((it, i) => {
            const need = deptItemNeed(d, it), s = deptItemShort(d, it);
            return `<tr><td style="text-align:center;">${i + 1}</td><td style="text-align:right !important; font-weight:600;">${escHtml(it.name)}</td><td style="text-align:center; font-size:1rem !important;">${need}</td><td style="text-align:center; font-size:1rem !important;">${(() => { const h = deptItemHaveInfo(d, it); return h ? `${h.have}${h.src !== 'manual' ? ' <small style="color:#8a8b8c;">(من الجرد)</small>' : ''}` : 'لم يُعد'; })()}</td><td style="text-align:center; font-size:1rem !important;">${s ? s : (s === 0 ? '✓' : '—')}</td></tr>`;
        }).join('');
        const info = `<tr><td colspan="5" style="text-align:right !important; background:#fef2ce; font-weight:600;">${isBuffetArea(d) ? 'بوفيه' : `إجمالي المكاتب (المتفق عليه): ${Number(d.offices) || '—'}`}${d.group ? `   ·   ${currentLang === 'en' ? 'Under: ' : 'تابع: '}${escHtml(d.group)}` : ''}${d.notes ? `   ·   ${escHtml(d.notes)}` : ''}</td></tr>`;
        const buy = deptShortMap(d);
        const foot = `<tr><th colspan="5" style="text-align:right !important;">محتاج يتشترى: ${buy.length ? buy.map(([n, q]) => `${escHtml(n)} ${q}`).join(' · ') : 'لا يوجد'}</th></tr>`;
        const head = `<tr><th style="text-align:center; width:40px;">م</th><th>الغرض</th><th style="text-align:center;">العدد المطلوب</th><th style="text-align:center;">الموجود حالياً</th><th style="text-align:center;">محتاج شراء</th></tr>`;
        printCgTable(title, `${isAr ? 'تاريخ التقرير:' : 'Date:'} ${getFormattedTodayDate(isAr)}`, 5, head, info + body, foot);
        return;
    }

    // Floor(s): same layout as the program and the Excel — one row per item (required · current · to buy),
    // department name and agreed offices beside its items; floor total and asset comparison under each floor; buffet in its own table
    const buffetList = list.filter(isBuffetArea);
    list = list.filter(d => !isBuffetArea(d));
    const c = 'text-align:center;';
    const itemRows = (d, withOffices, nameExtra) => {
        const items = (d.items || []).filter(it => it.name);
        const n = Math.max(items.length, 1);
        const lead = `<td rowspan="${n}" style="text-align:right !important; vertical-align:top; font-weight:700; border-top:1.5px solid #e8e0cb;">${escHtml(d.name)}${nameExtra || ''}${d.group ? `<br><small style="font-weight:400; color:#8a8b8c;">${currentLang === 'en' ? 'Under: ' : 'تابع: '}${escHtml(d.group)}</small>` : ''}${d.notes ? `<br><small style="font-weight:400; color:#8a8b8c;">${escHtml(d.notes)}</small>` : ''}</td>${withOffices ? `<td rowspan="${n}" style="${c} font-weight:700; border-top:1.5px solid #e8e0cb;">${Number(d.offices) || '—'}</td>` : ''}`;
        if (!items.length) return `<tr>${lead}<td colspan="4" style="${c} color:#8a8b8c;">—</td></tr>`;
        return items.map((it, k) => {
            const h = deptItemHaveInfo(d, it), s = deptItemShort(d, it);
            const top = k === 0 ? ' border-top:1.5px solid #e8e0cb;' : '';
            return `<tr>${k === 0 ? lead : ''}<td style="text-align:right !important;${top}">${escHtml(it.name)}</td><td style="${c}${top}">${deptItemNeed(d, it)}</td><td style="${c}${top}">${h ? h.have : '؟'}</td><td style="${c}${top}${s ? ' color:#b3261e; font-weight:700;' : ''}">${s === null ? '—' : s}</td></tr>`;
        }).join('');
    };
    const totRow = (label, ds, withOffices, offices) => {
        const t = deptListTotals(ds);
        return `<tr><td style="text-align:right !important; font-weight:700; background:#fef2ce;">${label}</td>${withOffices ? `<td style="${c} font-weight:700; background:#fef2ce;">${offices}</td>` : ''}<td style="background:#fef2ce;"></td><td style="${c} font-weight:700; background:#fef2ce;">${t.need}</td><td style="${c} font-weight:700; background:#fef2ce;">${t.have}</td><td style="${c} font-weight:700; background:#fef2ce;${t.short ? ' color:#b3261e;' : ''}">${t.short}</td></tr>`;
    };
    const N = 6;
    let body = '';
    floors.forEach(fl => {
        const depts = list.filter(d => d.floor === fl);
        if (!depts.length) return;
        const flOffices = depts.reduce((s, d) => s + (Number(d.offices) || 0), 0);
        if (floors.length > 1) body += `<tr><td colspan="${N}" style="text-align:right !important; font-weight:700; color:#94700f; background:#fbf8f1;">${fl} — ${depts.length} قسم · ${flOffices} مكتب</td></tr>`;
        depts.forEach(d => { body += itemRows(d, true); });
        body += totRow(`إجمالي ${fl}`, depts, true, flOffices);
        const cmp = deptAssetCompareHtml(depts, fl);
        if (cmp) body += `<tr><td colspan="${N}" style="text-align:right !important; font-size:0.72rem !important; color:#55524b;">${cmp.replace(/<\/span><span class="dept-cmp-chip">/g, '</span>   ·   <span>').replace(/class="warn"/g, 'style="color:#b26a00;"').replace(/class="bad"/g, 'style="color:#b3261e;"')}</td></tr>`;
    });
    const buyAll = deptShortMap(null, list);
    const foot = `<tr><th colspan="${N}" style="text-align:right !important;">محتاج يتشترى: ${buyAll.length ? buyAll.map(([n, q]) => `${escHtml(n)} ${q}`).join(' · ') : 'لا يوجد'}</th></tr>`;
    const head = `<tr><th style="width:24%;">القسم / المكتب</th><th style="${c} width:12%;">إجمالي المكاتب<br><small>المتفق عليه</small></th><th style="width:22%;">الغرض</th><th style="${c} width:14%;">العدد المطلوب</th><th style="${c} width:14%;">الموجود حالياً</th><th style="${c} width:14%;">محتاج شراء</th></tr>`;

    // Buffet table (same item rows, no offices column), printed under the offices with its own heading
    let extra = '';
    if (buffetList.length) {
        let bbody = '';
        DEPT_FLOORS.forEach(fl => {
            buffetList.filter(d => d.floor === fl).forEach(d => { bbody += itemRows(d, false, opts.floor || String(d.name).includes(fl) ? '' : ` <small>(${fl})</small>`); });
        });
        const bbuy = deptShortMap(null, buffetList);
        extra = `
            <div class="cg-print-section-title">البوفيه</div>
            <table class="print-table cg-fit-table" style="margin-top:4px;">
                <thead><tr><th style="width:30%;">البوفيه</th><th style="width:28%;">الغرض</th><th style="${c} width:14%;">العدد المطلوب</th><th style="${c} width:14%;">الموجود حالياً</th><th style="${c} width:14%;">محتاج شراء</th></tr></thead>
                <tbody>${bbody}</tbody>
                <tfoot><tr><th colspan="5" style="text-align:right !important;">محتاج يتشترى للبوفيه: ${bbuy.length ? bbuy.map(([n, q]) => `${escHtml(n)} ${q}`).join(' · ') : 'لا يوجد'}</th></tr></tfoot>
            </table>`;
    }
    const subtitle = `${isAr ? 'تاريخ التقرير:' : 'Date:'} ${getFormattedTodayDate(isAr)}`;
    if (!list.length && buffetList.length) {
        // only a buffet on this floor
        printCgTable(title, subtitle, 2, `<tr><th colspan="2" style="text-align:right !important;">لا توجد مكاتب مسجلة</th></tr>`, '', '', extra);
        return;
    }
    printCgTable(title, subtitle, N, buffetList.length ? `<tr><th colspan="${N}" style="text-align:right !important; background:#fff !important; font-size:0.9rem !important;">المكاتب والأقسام</th></tr>` + head : head, body, foot, extra);
}
